import { Point } from './point.js';
import { Utils } from '../lib/utils.js';
import { Strings } from '../lib/strings.js';
import { Entity } from './entity.js';
import { Input, PromptOptions } from '../lib/inputManager.js';
import { Logging } from '../lib/logging.js';
import { DXFFile } from '../lib/dxf/dxfFile.js';
import { BoundingBox } from '../lib/boundingBox.js';


import { DesignCore } from '../designCore.js';
import { Property } from '../properties/property.js';
import { SnapPoint } from '../lib/auxiliary/snapPoint.js';
import { RubberBand } from '../lib/auxiliary/rubberBand.js';

/**
 * Arc Entity Class
 * @extends Entity
 * */
export class Arc extends Entity {
  static type = 'Arc';

  /**
   * Create an Arc Entity
   * @param {Array} data
   */
  constructor(data) {
    super(data);

    // If only the centre point is present, project start/end from named scalar properties.
    // Full-points data (post-execute or post-fromDxf) skips this block entirely.
    if (data && this.points.length < 2) {
      const radius = data.radius ?? 1;
      if (data.hasOwnProperty('startAngle')) {
        this.points[1] = this.points[0].project(Utils.degrees2radians(data.startAngle), radius);
      }
      if (data.hasOwnProperty('endAngle')) {
        this.points[2] = this.points[0].project(Utils.degrees2radians(data.endAngle), radius);
      }
    }

    // direction: ccw > 0, cw <= 0
    this.properties.add(Property.Names.DIRECTION, {
      type: Property.Type.NUMBER,
      value: data?.direction ?? 1,
      dxfCode: 73,
    });

    // radius: computed from points — stored in EntityProperties
    this.properties.add(Property.Names.RADIUS, {
      type: Property.Type.NUMBER,
      get: (entity) => entity.points[1] ? entity.points[0].distance(entity.points[1]) : 1,
      dxfCode: 40,
    });
  }

  /**
   * Register the command
   * @return {Object}
   * command = name of the command
   * shortcut = shortcut for the command
   * type = type to group command in toolbars (omitted if not shown)
   */
  static register() {
    const command = { command: 'Arc', shortcut: 'A', type: 'Entity' };
    return command;
  }

  /**
   * Normalise DXF group codes into the canonical points-based representation.
   * Called by the DXF loader before construction.
   * @param {Object} data
   * @return {Object}
   */
  static fromDxf(data) {
    const centre = data.points?.[0];
    if (!centre) return data;
    // validate required group codes for points-based arc representation are present
    if (data[40] === undefined || data[50] === undefined || data[51] === undefined) return data;

    const radius = data[40];
    return {
      ...data,
      points: [
        centre,
        centre.project(Utils.degrees2radians(data[50] ?? 0), radius),
        centre.project(Utils.degrees2radians(data[51] ?? 0), radius),
      ],
      direction: data[73] ?? 1,
    };
  }

  /**
   * Execute method
   * executes the workflow, requesting input required to create an entity
   */
  async execute() {
    try {
      const op = new PromptOptions(Strings.Input.CENTER, [Input.Type.POINT]);
      const pt = await DesignCore.Scene.inputManager.requestInput(op);
      if (pt === undefined) return;
      this.points.push(pt);

      let pt1;
      while (true) {
        const op1 = new PromptOptions(Strings.Input.START, [Input.Type.POINT]);
        pt1 = await DesignCore.Scene.inputManager.requestInput(op1);
        if (pt1 === undefined) return;
        if (pt1.isSame?.(pt)) {
          DesignCore.Core.notify(`${this.type} - ${Strings.Error.INVALIDPOINT}`);
          continue;
        }
        break;
      }
      this.points.push(pt1);

      let pt2;
      while (true) {
        DesignCore.Scene.inputManager.inputPoint = pt; // polar/ortho tracks from centre on each attempt
        const op2 = new PromptOptions(`${Strings.Input.END} ${Strings.Strings.OR} ${Strings.Input.ANGLE}`, [Input.Type.POINT, Input.Type.NUMBER]);
        pt2 = await DesignCore.Scene.inputManager.requestInput(op2);
        if (pt2 === undefined) return;

        if (Input.getType(pt2) === Input.Type.POINT) {
          // Must not be same as centre or start
          const centre = this.points[0];
          const start = this.points[1];
          if (pt2.isSame?.(centre) || pt2.isSame?.(start)) {
            DesignCore.Core.notify(`${this.type} - ${Strings.Error.INVALIDPOINT}`);
            continue;
          }

          const angle = this.points[0].angle(pt2);
          const projectedEnd = this.points[0].project(angle, this.getProperty(Property.Names.RADIUS));
          if (projectedEnd.isSame(this.points[1])) {
            DesignCore.Core.notify(`${this.type} - ${Strings.Error.INVALIDPOINT}`);
            continue;
          }
          this.points.push(projectedEnd);

          // Infer arc direction using cross product if we have 3 points
          if (this.points.length === 3) {
            this.setProperty(Property.Names.DIRECTION, Arc.#inferDirection(this.points[0], this.points[1], this.points[2]));
            // Check total angle > 1 degree
            if (Math.abs(this.totalAngle) <= 1) {
              this.points.pop(); // Remove invalid end point
              DesignCore.Core.notify(`${this.type} - ${Strings.Error.INVALIDNUMBER}: ${Strings.Error.MINVALUE}`);
              continue;
            }
          }
          break;
        } else if (Input.getType(pt2) === Input.Type.NUMBER) {
          // Must be a valid angle in (0, 360]
          const angleValue = Number(pt2);
          if (!Number.isFinite(angleValue) || Math.abs(angleValue) <= 0 || Math.abs(angleValue) > 360) {
            DesignCore.Core.notify(`${this.type} - ${Strings.Error.INVALIDNUMBER}`);
            continue;
          }
          const basePoint = this.points.at(0);
          const startPoint = this.points.at(1);
          const angle = Utils.degrees2radians(angleValue);
          const point = startPoint.rotate(basePoint, angle);
          this.points.push(point);
          // Set direction based on sign of angle
          this.setProperty(Property.Names.DIRECTION, angle >= 0 ? 1 : -1);
          // Check total angle > 1 degree
          if (Math.abs(this.totalAngle) <= 1) {
            this.points.pop(); // Remove invalid end point
            DesignCore.Core.notify(`${this.type} - ${Strings.Error.INVALIDNUMBER}: ${Strings.Error.MINVALUE}`);
            continue;
          }
          break;
        } else {
          DesignCore.Core.notify(`${this.type} - ${Strings.Error.INPUT}`);
        }
      }

      DesignCore.Scene.inputManager.executeCommand(this);
    } catch (err) {
      Logging.instance.error(`${this.type} - ${err}`);
    }
  }

  /**
   * Preview the entity during creation
   */
  preview() {
    if (this.points.length >= 1) {
      const mousePoint = DesignCore.Mouse.pointOnScene();
      DesignCore.Scene.auxiliaryEntities.add(new RubberBand([this.points.at(0), mousePoint]));
    }

    if (this.points.length >= 2) {
      const mousePoint = DesignCore.Mouse.pointOnScene();
      // const points = [...this.points, mousePoint];
      const centre = this.points[0];
      const endPoint = centre.project(centre.angle(mousePoint), this.getProperty(Property.Names.RADIUS));
      if (endPoint.isSame(this.points[1])) return;
      const points = [...this.points, endPoint];

      // Infer direction for preview, so it matches what will be created
      let direction = 1;
      if (points.length === 3) {
        direction = Arc.#inferDirection(points[0], points[1], points[2]);
      }

      DesignCore.Scene.previewEntities.create(this.type, { points: points, direction: direction });
    }
  }

  /**
   * Infer arc direction from three points using cross product
   * @param {Point} centre
   * @param {Point} start
   * @param {Point} end
   * @return {number} 1 for ccw, -1 for cw
   */
  static #inferDirection(centre, start, end) {
    // All points must be defined and distinct
    if (!centre || !start || !end) {
      return 1; // Default to counterclockwise
    }
    if (centre.isSame?.(start) || centre.isSame?.(end) || start.isSame?.(end)) {
      return 1;
    }

    const v1 = start.subtract(centre);
    const v2 = end.subtract(centre);
    const cross = v1.cross(v2);
    const direction = cross > 0 ? 1 : -1;
    return direction;
  }

  /**
   * Arc start angle
   * @return {number} start angle in radians
   */
  startAngle() {
    return this.points[0].angle(this.points[1]);
  }

  /**
   * Arc end angle
   * @return {number} end angle in radians
   */
  endAngle() {
    const endAngle = this.points[0].angle(this.points[2]);
    return endAngle;
  }

  /**
   * Calculate the angle between the start and end of the arc
   * Clockwise returns positive angle
   * Counter clockwise returns negative
   * @return {number} angle in degrees
   */
  get totalAngle() {
    let startAngle = this.startAngle();
    let endAngle = this.endAngle();


    if (this.getProperty(Property.Names.DIRECTION) > 0) {
      if (startAngle > endAngle || startAngle === endAngle) {
        endAngle += (Math.PI * 2);
      }
    } else {
      startAngle += (Math.PI * 2);
    }

    const totalAngle = (startAngle - endAngle);
    return Utils.radians2degrees(totalAngle);
  }

  /**
   * Get Arc radius
   * @return {number} - arc radius
   */
  getRadius() {
    return this.getProperty(Property.Names.RADIUS);
  }

  /**
   * Draw the entity
   * @param {Object} ctx - context
   * @param {number} scale
   */
  /**
   * Draw the arc
   * @param {Object} renderer
   */
  draw(renderer) {
    renderer.drawShape(this.toPolylinePoints());
  }

  /**
   * Write the entity to file in the dxf format
   * @param {DXFFile} file
   */
  dxf(file) {
    file.writeGroupCode('0', 'ARC');
    file.writeGroupCode('5', this.getProperty(Property.Names.HANDLE), DXFFile.Version.R2000); // Handle
    file.writeGroupCode('100', 'AcDbEntity', DXFFile.Version.R2000);
    file.writeGroupCode('100', 'AcDbCircle', DXFFile.Version.R2000);
    file.writeGroupCode('8', this.getProperty(Property.Names.LAYER)); // LAYERNAME
    file.writeGroupCode('6', this.getProperty(Property.Names.LINETYPE)); // LINETYPE
    file.writeGroupCode('10', this.points[0].x); // X
    file.writeGroupCode('20', this.points[0].y); // Y
    file.writeGroupCode('30', '0.0'); // Z
    file.writeGroupCode('39', this.getProperty(Property.Names.LINEWIDTH)); // Line Width
    file.writeGroupCode('40', this.getProperty(Property.Names.RADIUS)); // Radius
    file.writeGroupCode('100', 'AcDbArc', DXFFile.Version.R2000);
    file.writeGroupCode('50', Utils.radians2degrees(this.getProperty(Property.Names.DIRECTION) > 0 ? this.startAngle() : this.endAngle())); // Start Angle
    file.writeGroupCode('51', Utils.radians2degrees(this.getProperty(Property.Names.DIRECTION) > 0 ? this.endAngle() : this.startAngle())); // End Angle
  }

  /**
   * Return a list of points representing a polyline version of this entity
   * @return {Array}
   */
  toPolylinePoints() {
    // counter clockwise bulge = +ve, clockwise bulge = -ve,
    // ccw arc = 0, clockwise arc = 1

    // If the arc forms a complete circle
    // Split into two separate polyline arcs
    const radius = this.getProperty(Property.Names.RADIUS);
    if (Math.abs(this.totalAngle) === 360) {
      const startPoint = this.points[0].project(0, radius);
      startPoint.bulge = 1;
      const endPoint = this.points[0].project(0, -radius);
      endPoint.bulge = 1;
      const closurePoint = this.points[0].project(0, radius);
      return [startPoint, endPoint, closurePoint];
    }

    const startPoint = this.points[0].project(this.startAngle(), radius);
    const bulge = Math.tan(Utils.degrees2radians(-this.totalAngle % 360) / 4);
    startPoint.bulge = bulge;
    const endPoint = this.points[0].project(this.endAngle(), radius);
    return [startPoint, endPoint];
  }

  /**
   * Set entity points from a polyline point representation
   * @param {Array} points
   * @return {Arc}
   */
  fromPolylinePoints(points) {
    const centre = points[0].bulgeCentrePoint(points[1]);
    this.points = [centre, new Point(points[0].x, points[0].y), new Point(points.at(-1).x, points.at(-1).y)];
    return this;
  }

  /**
   * Get snap points
   * @param {Point} mousePoint
   * @param {number} delta
   * @return {Array} - array of snap points
   */
  snaps(mousePoint, delta) {
    const snaps = [];

    const centre = this.points[0]; // arc centre point
    const arcStartPoint = this.points[1]; // arc start point on circumference
    const arcEndPoint = this.points[2]; // arc end point on circumference

    snaps.push(new SnapPoint(centre, SnapPoint.Type.CENTRE));
    snaps.push(new SnapPoint(arcStartPoint, SnapPoint.Type.END));
    snaps.push(new SnapPoint(arcEndPoint, SnapPoint.Type.END));

    if (mousePoint) {
      const [nearestPoint, nearestDistance, isOnArc] = this.closestPoint(mousePoint);
      // Crude way to snap to the closest point on the arc
      if (isOnArc === true && nearestDistance < delta / 10) {
        snaps.push(new SnapPoint(nearestPoint, SnapPoint.Type.NEAREST));
      }
    }

    const fromPoint = DesignCore.Scene.inputManager.inputPoint; // last confirmed input point (line start)
    if (fromPoint !== null) {
      const distanceToCenter = centre.distance(fromPoint); // distance from the input point to the arc centre
      const angleFromCentreToInput = centre.angle(fromPoint); // angle from centre toward fromPoint

      // Tangent: only possible when fromPoint is outside the arc radius
      const radius = this.getProperty(Property.Names.RADIUS);
      const direction = this.getProperty(Property.Names.DIRECTION);
      if (distanceToCenter > radius) {
        const tangentHalfAngle = Math.acos(radius / distanceToCenter); // half-angle between the two tangent directions

        for (const sign of [1, -1]) {
          const tangentPoint = centre.project(angleFromCentreToInput + sign * tangentHalfAngle, radius);
          if (tangentPoint.isOnArc(this.points[1], this.points[2], centre, direction)) {
            snaps.push(new SnapPoint(tangentPoint, SnapPoint.Type.TANGENT));
          }
        }
      }

      // Perpendicular: point on the arc that lies on the line from fromPoint through the centre
      if (distanceToCenter > 0) {
        const perpendicularPoint = centre.project(angleFromCentreToInput, radius);
        if (perpendicularPoint.isOnArc(this.points[1], this.points[2], centre, direction)) {
          snaps.push(new SnapPoint(perpendicularPoint, SnapPoint.Type.PERPENDICULAR));
        }
      }
    }

    return snaps;
  }

  /**
   * Get closest point on entity
   * @param {Point} P
   * @return {Array} - [Point, distance]
   */
  closestPoint(P) {
    const startPoint = this.points[1];
    const endPoint = this.points[2];
    const centrePoint = this.points[0];

    const pnt = P.closestPointOnArc(startPoint, endPoint, centrePoint, this.getProperty(Property.Names.DIRECTION));

    if (pnt !== null) {
      const distance = P.distance(pnt);
      return [pnt, distance, true];
    }

    // closest point not on the arc
    return [P, Infinity, false];
  }

  /**
   * Return boundingbox for entity
   * @return {BoundingBox}
   */
  boundingBox() {
    return BoundingBox.arcBoundingBox(this.points[0], this.points[1], this.points[2], this.getProperty(Property.Names.DIRECTION));
  }
}
